import sys
from enum import Enum, unique

import fire

from .generate import vllm_generate
from .grader import evaluate


@unique
class Command(str, Enum):
    EVAL = "eval"
    GEN = "gen"


def main():
    command = sys.argv.pop(1) if len(sys.argv) != 1 else None
    if command == Command.EVAL:
        fire.Fire(evaluate)
    elif command == Command.GEN:
        fire.Fire(vllm_generate)
    else:
        print("Please use `mathruler eval` or `mathruler gen`.")


if __name__ == "__main__":
    main()

"""
Answer checker API that uses sympy to simplify expressions and check for equality.

Call grade_answer(given_answer: str, ground_truth: str).

This code is largely borrowed from: https://github.com/openai/prm800k/blob/main/prm800k/grading/grader.py
"""

import json
import re

import sympy
from pylatexenc import latex2text
from sympy.parsing import sympy_parser
from tqdm import tqdm

from .math_normalize import normalize_answer


# sympy might hang -- we don't care about trying to be lenient in these cases
BAD_SUBSTRINGS = ["^{", "^("]
BAD_REGEXES = [r"\^[0-9]+\^", r"\^[0-9][0-9]+"]
TUPLE_CHARS = "()[]"


def _sympy_parse(expr: str):
    """Parses an expression with sympy."""
    py_expr = expr.replace("^", "**")
    return sympy_parser.parse_expr(
        py_expr,
        transformations=(sympy_parser.standard_transformations + (sympy_parser.implicit_multiplication_application,)),
    )


def _parse_latex(expr: str) -> str:
    """Attempts to parse latex to an expression sympy can read."""
    expr = expr.replace("\\tfrac", "\\frac")
    expr = expr.replace("\\dfrac", "\\frac")
    expr = expr.replace("\\frac", " \\frac")  # Play nice with mixed numbers.
    expr = latex2text.LatexNodes2Text().latex_to_text(expr)

    # Replace the specific characters that this parser uses.
    expr = expr.replace("√", "sqrt")
    expr = expr.replace("π", "pi")
    expr = expr.replace("∞", "inf")
    expr = expr.replace("∪", "U")
    expr = expr.replace("·", "*")
    expr = expr.replace("×", "*")

    return expr.strip()


def _is_float(num: str) -> bool:
    try:
        float(num)
        return True
    except ValueError:
        return False


def _is_int(x: float) -> bool:
    try:
        return abs(x - int(round(x))) <= 1e-7
    except:
        return False


def _is_frac(expr: str) -> bool:
    return bool(re.search(r"^-?[0-9]+.?/0*[1-9][0-9]*.?$", expr))


def _str_is_int(x: str) -> bool:
    try:
        x = _strip_properly_formatted_commas(x)
        x = float(x)
        return abs(x - int(round(x))) <= 1e-7
    except:
        return False


def _str_to_int(x: str) -> bool:
    x = x.replace(",", "")
    x = float(x)
    return int(x)


def _inject_implicit_mixed_number(step: str):
    """
    Automatically make a mixed number evalable
    e.g. 7 3/4 => 7+3/4
    """
    p1 = re.compile("([0-9]) +([0-9])")
    step = p1.sub("\\1+\\2", step)  ## implicit mults
    return step


def _strip_properly_formatted_commas(expr: str):
    # We want to be careful because we don't want to strip tuple commas
    p1 = re.compile(r"(\d)(,)(\d\d\d)($|\D)")
    while True:
        next_expr = p1.sub("\\1\\3\\4", expr)
        if next_expr == expr:
            break
        expr = next_expr
    return next_expr


def _normalize(expr: str) -> str:
    """Normalize answer expressions."""
    if expr is None:
        return None

    # Remove enclosing `\text{}`.
    m = re.search(r"^\\text\{(?P<text>.+?)\}$", expr)
    if m is not None:
        expr = m.group("text")

    expr = expr.replace("\\%", "%")
    expr = expr.replace("\\$", "$")
    expr = expr.replace("$", "")
    expr = expr.replace("%", "")
    expr = expr.replace(" or ", " , ")
    expr = expr.replace(" and ", " , ")

    expr = expr.replace("million", "*10^6")
    expr = expr.replace("billion", "*10^9")
    expr = expr.replace("trillion", "*10^12")

    for unit in [
        "degree",
        "cm",
        "centimeter",
        "meter",
        "mile",
        "second",
        "minute",
        "hour",
        "day",
        "week",
        "month",
        "year",
        "foot",
        "feet",
        "inch",
        "yard",
    ]:
        expr = re.sub(rf"{unit}(es)?(s)? *(\^[0-9]+)?", "", expr)
    expr = re.sub(r"\^ *\\circ", "", expr)

    if len(expr) > 0 and expr[0] == "{" and expr[-1] == "}":
        expr = expr[1:-1]

    expr = re.sub(",\\\\! *", "", expr)
    if _is_float(expr) and _is_int(float(expr)):
        expr = str(int(round(float(expr))))
    if "\\" in expr:
        try:
            expr = _parse_latex(expr)
        except:
            pass

    # edge case with mixed numbers and negative signs
    expr = re.sub("- *", "-", expr)

    expr = _inject_implicit_mixed_number(expr)
    expr = expr.replace(" ", "")

    # if we somehow still have latex braces here, just drop them
    expr = expr.replace("{", "")
    expr = expr.replace("}", "")

    # don't be case sensitive for text answers
    expr = expr.lower()

    if _str_is_int(expr):
        expr = str(_str_to_int(expr))

    return expr


def count_unknown_letters_in_expr(expr: str):
    expr = expr.replace("sqrt", "")
    expr = expr.replace("frac", "")
    letters_in_expr = {x for x in expr if x.isalpha()}
    return len(letters_in_expr)


def should_allow_eval(expr: str):
    # we don't want to try parsing unknown text or functions of more than two variables
    if count_unknown_letters_in_expr(expr) > 2:
        return False

    for bad_string in BAD_SUBSTRINGS:
        if bad_string in expr:
            return False

    for bad_regex in BAD_REGEXES:
        if re.search(bad_regex, expr) is not None:
            return False

    return True


def are_equal_under_sympy(ground_truth_normalized: str, given_normalized: str):
    are_equal = False
    try:
        expr = f"({ground_truth_normalized})-({given_normalized})"
        if should_allow_eval(expr):
            sympy_diff = _sympy_parse(expr)
            simplified = sympy.simplify(sympy_diff)
            if simplified == 0:
                are_equal = True
    except:
        pass
    return are_equal


def split_tuple(expr: str):
    """
    Split the elements in a tuple/interval, while handling well-formatted commas in large numbers
    """
    expr = _strip_properly_formatted_commas(expr)
    if len(expr) == 0:
        return []
    if (
        len(expr) > 2
        and expr[0] in TUPLE_CHARS
        and expr[-1] in TUPLE_CHARS
        and all([ch not in expr[1:-1] for ch in TUPLE_CHARS])
    ):
        elems = [elem.strip() for elem in expr[1:-1].split(",")]
    else:
        elems = [expr]
    return elems


def grade_answer(given_answer: str, ground_truth: str) -> bool:
    """
    The answer will be considered correct if:
    (a) it normalizes to the same string as the ground truth answer
    OR
    (b) sympy can simplify the difference between the expressions to 0
    """
    if given_answer is None:
        return False

    ground_truth_normalized_mathd = normalize_answer(ground_truth)
    given_answer_normalized_mathd = normalize_answer(given_answer)

    # be at least as lenient as mathd
    if ground_truth_normalized_mathd == given_answer_normalized_mathd:
        return True

    ground_truth_normalized = _normalize(ground_truth)
    given_normalized = _normalize(given_answer)

    if ground_truth_normalized is None:
        return False

    if ground_truth_normalized == given_normalized:
        return True

    if len(given_normalized) == 0:
        return False

    ground_truth_elems = split_tuple(ground_truth_normalized)
    given_elems = split_tuple(given_normalized)

    if len(ground_truth_elems) > 1 and (
        ground_truth_normalized[0] != given_normalized[0] or ground_truth_normalized[-1] != given_normalized[-1]
    ):
        is_correct = False
    elif len(ground_truth_elems) != len(given_elems):
        is_correct = False
    else:
        for ground_truth_elem, given_elem in zip(ground_truth_elems, given_elems):
            if _is_frac(ground_truth_elem) and _is_frac(given_elem):
                # if fractions aren't reduced, then shouldn't be marked as correct
                # so, we don't want to allow sympy.simplify in this case
                is_correct = ground_truth_elem == given_elem
            elif _str_is_int(ground_truth_elem) != _str_is_int(given_elem):
                # if the ground truth answer is an integer, we require the given answer to be a strict match (no sympy.simplify)
                is_correct = False
            else:
                is_correct = are_equal_under_sympy(ground_truth_elem, given_elem)
            if not is_correct:
                break

    return is_correct


def extract_boxed_content(text: str) -> str:
    """
    Extracts answers in \\boxed{}.
    """
    depth = 0
    start_pos = text.rfind(r"\boxed{")
    end_pos = -1
    if start_pos != -1:
        content = text[start_pos + len(r"\boxed{") :]
        for i, char in enumerate(content):
            if char == "{":
                depth += 1
            elif char == "}":
                depth -= 1

            if depth == -1:  # exit
                end_pos = i
                break

    if end_pos != -1:
        return content[:end_pos].strip()

    return "None"


def evaluate(json_path: str, verbose: bool = False):
    n_correct, n_total = 0, 0
    with open(json_path, encoding="utf-8") as f:
        lines = f.readlines()

    for line in tqdm(lines, desc="Processing samples", disable=verbose):
        sample = json.loads(line)
        if "predicts" in sample:
            is_correct = False
            for predict in sample["predicts"]:
                is_correct |= grade_answer(extract_boxed_content(predict), sample["answer"])
        else:
            is_correct = grade_answer(extract_boxed_content(sample["solution"]), sample["answer"])

        n_correct += int(is_correct)
        n_total += 1
        if verbose and not is_correct:
            print(sample)

    print(f"Accuracy: {n_correct}/{n_total} = {n_correct / n_total * 100:.2f}%.")

"""
This logic is largely copied from the Hendrycks' MATH release (math_equivalence).

https://github.com/openai/prm800k/blob/main/prm800k/grading/math_normalize.py
"""

import re
from typing import Optional


def normalize_answer(answer: Optional[str]) -> Optional[str]:
    if answer is None:
        return None
    answer = answer.strip()
    try:
        # Remove enclosing `\text{}`.
        m = re.search(r"^\\text\{(?P<text>.+?)\}$", answer)
        if m is not None:
            answer = m.group("text").strip()
        return _strip_string(answer)
    except:
        return answer


def _fix_fracs(string):
    substrs = string.split("\\frac")
    new_str = substrs[0]
    if len(substrs) > 1:
        substrs = substrs[1:]
        for substr in substrs:
            new_str += "\\frac"
            if substr[0] == "{":
                new_str += substr
            else:
                try:
                    assert len(substr) >= 2
                except:
                    return string
                a = substr[0]
                b = substr[1]
                if b != "{":
                    if len(substr) > 2:
                        post_substr = substr[2:]
                        new_str += "{" + a + "}{" + b + "}" + post_substr
                    else:
                        new_str += "{" + a + "}{" + b + "}"
                else:
                    if len(substr) > 2:
                        post_substr = substr[2:]
                        new_str += "{" + a + "}" + b + post_substr
                    else:
                        new_str += "{" + a + "}" + b
    string = new_str
    return string


def _fix_a_slash_b(string):
    if len(string.split("/")) != 2:
        return string
    a = string.split("/")[0]
    b = string.split("/")[1]
    try:
        a = int(a)
        b = int(b)
        assert string == f"{a}/{b}"
        new_string = "\\frac{" + str(a) + "}{" + str(b) + "}"
        return new_string
    except:
        return string


def _remove_right_units(string):
    # "\\text{ " only ever occurs (at least in the val set) when describing units
    if "\\text{ " in string:
        splits = string.split("\\text{ ")
        assert len(splits) == 2
        return splits[0]
    else:
        return string


def _fix_sqrt(string):
    if "\\sqrt" not in string:
        return string
    splits = string.split("\\sqrt")
    new_string = splits[0]
    for split in splits[1:]:
        if split[0] != "{":
            a = split[0]
            new_substr = "\\sqrt{" + a + "}" + split[1:]
        else:
            new_substr = "\\sqrt" + split
        new_string += new_substr
    return new_string


def _strip_string(string):
    # linebreaks
    string = string.replace("\n", "")
    # print(string)

    # remove inverse spaces
    string = string.replace("\\!", "")
    # print(string)

    # replace \\ with \
    string = string.replace("\\\\", "\\")
    # print(string)

    # replace tfrac and dfrac with frac
    string = string.replace("tfrac", "frac")
    string = string.replace("dfrac", "frac")
    # print(string)

    # remove \left and \right
    string = string.replace("\\left", "")
    string = string.replace("\\right", "")
    # print(string)

    # Remove circ (degrees)
    string = string.replace("^{\\circ}", "")
    string = string.replace("^\\circ", "")

    # remove dollar signs
    string = string.replace("\\$", "")

    # remove units (on the right)
    string = _remove_right_units(string)

    # remove percentage
    string = string.replace(r"\%", "")
    string = string.replace(r"%", "")

    # " 0." equivalent to " ." and "{0." equivalent to "{." Alternatively, add "0" if "." is the start of the string
    string = string.replace(" .", " 0.")
    string = string.replace("{.", "{0.")
    # if empty, return empty string
    if len(string) == 0:
        return string
    if string[0] == ".":
        string = "0" + string

    # to consider: get rid of e.g. "k = " or "q = " at beginning
    if len(string.split("=")) == 2:
        if len(string.split("=")[0]) <= 2:
            string = string.split("=")[1]

    # fix sqrt3 --> sqrt{3}
    string = _fix_sqrt(string)

    # remove spaces
    string = string.replace(" ", "")

    # \frac1b or \frac12 --> \frac{1}{b} and \frac{1}{2}, etc. Even works with \frac1{72} (but not \frac{72}1). Also does a/b --> \\frac{a}{b}
    string = _fix_fracs(string)

    # manually change 0.5 --> \frac{1}{2}
    if string == "0.5":
        string = "\\frac{1}{2}"

DEFAULT_AIME = Path("/historical/shared/qat/data/raw/aime_2024/data/train-00000-of-00001.parquet")
DEFAULT_INSTRUCTION = (
    "Solve the following AIME problem. Think step by step, explain your reasoning, "
    "and finish with the integer answer in \\boxed{}."
)


def load_aime_records(path: Path, limit: Optional[int] = None) -> List[Dict[str, Any]]:
    """Read AIME parquet rows without requiring the datasets library."""

    try:
        import pyarrow.parquet as pq
    except ImportError as exc:  # pragma: no cover - environment dependent
        raise RuntimeError("AIME evaluation requires pyarrow") from exc
    rows = pq.read_table(path).to_pylist()
    result: List[Dict[str, Any]] = []
    for row in rows[: limit if limit is not None else None]:
        if not isinstance(row, dict) or "problem" not in row or "answer" not in row:
            raise ValueError(f"invalid AIME row in {path}: {row!r}")
        result.append(row)
    return result


def extract_answer(text: str) -> Optional[str]:
    """Extract an AIME integer, preferring boxed/final-answer conventions."""

    if not text:
        return None
    # Models use both LaTex \u005cboxed{123} and ``\\boxed{\\text{123}}``.
    boxed = re.findall(r"\\boxed\s*\{\s*(?:\\text\s*\{\s*)?(-?\d{1,3})", text)
    if boxed:
        return boxed[-1].lstrip("+")
    marked = re.findall(
        r"(?:final answer|answer|答案)\s*(?:is|=|：|:)\s*[^0-9-]*(-?\d{1,3})",
        text,
        flags=re.IGNORECASE,
    )
    if marked:
        return marked[-1].lstrip("+")
    # Last standalone 0--999 integer is a conservative fallback.  Restricting
    # to three digits avoids selecting years or intermediate large constants.
    numbers = re.findall(r"(?<![\w])-?\d{1,3}(?![\w])", text)
    return numbers[-1].lstrip("+") if numbers else None


def answers_equal(prediction: Optional[str], expected: str) -> bool:
    """Compare AIME answers numerically (``025`` and ``25`` are equivalent)."""

    if prediction is None:
        return False
    try:
        return 0 <= int(prediction) <= 999 and int(prediction) == int(str(expected).strip())
    except (TypeError, ValueError):
        return prediction.strip() == str(expected).strip()


def _messages(problem: str, instruction: str = DEFAULT_INSTRUCTION) -> List[Dict[str, str]]:
    return [{"role": "user", "content": f"{instruction}\n\n{problem}"}]


def _dtype(name: str, device: torch.device) -> torch.dtype:
    if name == "auto":
        return torch.bfloat16 if device.type == "cuda" and torch.cuda.is_bf16_supported() else torch.float32
    if name == "bf16":
        if device.type != "cuda" or not torch.cuda.is_bf16_supported():
            raise RuntimeError("bf16 evaluation requires a CUDA device with bf16 support")
        return torch.bfloat16
    if name == "fp16":
        return torch.float16
    return torch.float32


def _git_revision() -> Optional[str]:
    """Return the evaluator checkout revision when it is available.

    Evaluation reports are often copied away from the source checkout.  A
    best-effort revision makes those reports auditable without making a
    benchmark depend on git being installed (or on the workspace being a
    repository).  No error from this diagnostic should affect evaluation.
    """

    try:
        result = subprocess.run(
            ["git", "-C", str(Path(__file__).resolve().parents[1]), "rev-parse", "HEAD"],
            check=False,
            capture_output=True,
            text=True,
            timeout=5,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    revision = result.stdout.strip()
    return revision if result.returncode == 0 and revision else None


def _source_sha256() -> Optional[str]:
    """Hash this evaluator source for provenance of uncommitted changes."""

    try:
        digest = hashlib.sha256()
        with Path(__file__).open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
        return digest.hexdigest()
    except OSError:
        return None


def _resolved_dtype_name(dtype: torch.dtype) -> str:
    """Map the actual torch dtype to a stable report spelling."""

    names = {
        torch.float32: "fp32",
        torch.float16: "fp16",
        torch.bfloat16: "bf16",
    }
    return names.get(dtype, str(dtype).replace("torch.", ""))


def _load_model_and_tokenizer(args: argparse.Namespace, device: torch.device):
    try:
        import transformers
        from transformers import AutoModelForCausalLM, AutoTokenizer
    except ImportError as exc:  # pragma: no cover - environment dependent
        raise RuntimeError("AIME evaluation requires transformers") from exc
    version = tuple(int(part) for part in re.match(r"^(\d+)\.(\d+)", transformers.__version__).groups())
    if version < (4, 37):
        raise RuntimeError(
            f"Transformers {transformers.__version__} is too old for Qwen2; install >=4.37"
        )

#!/usr/bin/env python3
"""Load and score Minerva Math and OlympiadBench with SimpleRL's evaluator."""

from __future__ import annotations

import json
import os
from pathlib import Path
import sys
from typing import Any, Optional


DEFAULT_INSTRUCTION = (
    "Solve the following math problem. Think step by step, explain your reasoning, "
    "and put your final answer within \\boxed{}."
)
DEFAULT_SIMPLELR_ROOT = Path(
    "/historical/shared/qat/vendor/simpleRL-reason/examples/simplelr_math_eval"
)
DEFAULT_SIMPLELR_DEPS = Path("/historical/shared/qat/envs/simplelr-eval-pylibs")
SIMPLELR_NAMES = {
    "amc23": "amc23",
    "minerva_math": "minerva_math",
    "olympiad_bench": "olympiadbench",
}


def _simplelr_modules():
    root = Path(os.environ.get("SIMPLELR_MATH_EVAL_ROOT", DEFAULT_SIMPLELR_ROOT))
    deps = Path(os.environ.get("SIMPLELR_MATH_EVAL_DEPS", DEFAULT_SIMPLELR_DEPS))
    for path in (deps, root):
        value = str(path)
        if value not in sys.path:
            sys.path.insert(0, value)
    try:
        from grader import math_equal
        from parser import extract_answer, parse_ground_truth, parse_question
    except ImportError as exc:
        raise RuntimeError(
            f"SimpleRL math evaluator is unavailable under {root} (deps: {deps})"
        ) from exc
    return extract_answer, parse_ground_truth, parse_question, math_equal


def load_math_records(
    path: Path, benchmark: str, limit: Optional[int] = None
) -> list[dict[str, Any]]:
    """Load a full SimpleRL JSONL split and normalize its question/answer fields."""

    if benchmark not in SIMPLELR_NAMES:
        raise ValueError(f"unsupported math benchmark: {benchmark}")
    _, parse_ground_truth, parse_question, _ = _simplelr_modules()
    data_name = SIMPLELR_NAMES[benchmark]
    records: list[dict[str, Any]] = []
    with path.open("r", encoding="utf-8") as handle:
        for line_number, line in enumerate(handle, start=1):
            if not line.strip():
                continue
            row = json.loads(line)
            question = parse_question(row, data_name)
            _, answer = parse_ground_truth(row, data_name)
            if not question or answer is None:
                raise ValueError(f"invalid {benchmark} row {line_number} in {path}")
            normalized = dict(row)
            normalized["problem"] = question
            normalized["answer"] = str(answer)
            normalized.setdefault("id", normalized.get("idx", line_number - 1))
            records.append(normalized)
            if limit is not None and len(records) >= limit:
                break
    return records


def extract_math_answer(text: str, benchmark: str) -> Optional[str]:
    if benchmark not in SIMPLELR_NAMES:
        raise ValueError(f"unsupported math benchmark: {benchmark}")
    extract_answer, _, _, _ = _simplelr_modules()
    answer = extract_answer(text, SIMPLELR_NAMES[benchmark])
    return str(answer) if answer not in (None, "") else None


def math_answers_equal(prediction: Optional[str], expected: str) -> bool:
    if prediction is None:
        return False
    _, _, _, math_equal = _simplelr_modules()
    return bool(math_equal(prediction, expected, timeout=True))

