cd /tmp && python3 -I - <<'PY'
import sys,json,pandas as pd,os,importlib.util
from pathlib import Path
sys.path.insert(0,'/workspace/qat/vendor/verl')
spec=importlib.util.spec_from_file_location('mr','/workspace/math_reward.py')
m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
rows=pd.read_parquet('/workspace/data/skywork_or1_7b_math_difficulty1-15_16k.parquet')
gt={x[0]['content']:json.loads(y['ground_truth'])[0] for x,y in zip(rows.prompt,rows.reward_model)}
tot=old=new=0; fp=[]; fn=[]
for p in sorted(Path('/workspace/evidence/training').glob('steps-*/rollouts/*.jsonl')):
    for line in p.read_text().splitlines():
        try:r=json.loads(line)
        except:continue
        text=r['input'].removeprefix('<｜User｜>').removesuffix('<｜Assistant｜><think>\n')
        if text not in gt: print('MISSING'); continue
        res=m.compute_score('train-math-x',r['generation'],json.dumps([gt[text]]))
        tot+=1; old+=bool(r['acc']); new+=res['acc']
        if res['acc'] and not r['acc']: fn.append((p.name,res['pred'],gt[text]))
        if r['acc'] and not res['acc']: fp.append((p.name,res['pred'],gt[text],r['generation'][-200:]))
print('rollouts',tot,'old accepted',old,'new accepted',new,'newly credited',len(fn),'newly rejected',len(fp))
for x in fp[:10]: print('REJECTED',x)
os._exit(0)
PY

